import org.openenglish.reader.*;import android.content.Context;import java.io.*;import java.nio.file.*;import org.json.*;
public final class IslandMemoryTest {
 static int checks;static void check(boolean b,String n){if(!b)throw new AssertionError(n);checks++;System.out.println("PASS "+n);}
 public static void main(String[] args)throws Exception {File dir=Files.createTempDirectory("island-memory-").toFile();Context ctx=new Context(dir,dir);IslandMemory yue=new IslandMemory(ctx,"yue"),ja=new IslandMemory(ctx,"ja");yue.note("请慢一点，我想练点餐");yue.complete("我想飲凍奶茶", "好呀，少甜定正常甜？","茶餐厅");check(yue.count()==1,"completed pair saved");check(ja.count()==0&&ja.note().isEmpty(),"languages isolated");IslandMemory reopened=new IslandMemory(new Context(dir,dir),"yue");check(reopened.count()==1&&reopened.note().contains("慢一点"),"memory survives store reopening");check(reopened.context("我想點奶茶").contains("凍奶茶"),"old conversation contributes context");JSONArray h=reopened.history("唔該");check(h.length()==3&&h.getJSONObject(2).getString("content").equals("唔該"),"current utterance follows completed pairs");for(int i=0;i<305;i++)yue.complete("消息"+i,"回复"+i,"聊天");check(yue.count()==300,"bounded durable memory");check(yue.history("新问题").length()==5,"only two complete pairs in live history");check(yue.context("消息").length()<=1000,"prompt memory bounded");check(yue.display().contains("消息304"),"latest complete pair visible");ja.note("ゆっくり");yue.clear();check(yue.count()==0&&yue.note().isEmpty()&&yue.history("新问题").length()==1,"clear stops old context from reappearing");check(ja.note().equals("ゆっくり"),"clear scoped to one language");IslandReview review=new IslandReview(ctx);review.rate("lesson",0);IslandReview reopenReview=new IslandReview(new Context(dir,dir));check(reopenReview.card("lesson").lapses==1&&reopenReview.card("lesson").interval==1,"review due state durable");System.out.println("ISLAND_MEMORY_CHECKS: "+checks);}
}
